<?php require 'app/init.php';require 'app/view.php';$u=require_user();if($_SERVER['REQUEST_METHOD']==='POST'){verify();$id=(int)($_POST['libro_id']??0);$estado=$_POST['estado']??'pendiente';$progreso=max(0,min(100,(int)($_POST['progreso']??0)));if(in_array($estado,['pendiente','leyendo','terminado'],true)&&$id){$s=db()->prepare('INSERT INTO bibliotecas(usuario_id,libro_id,estado,progreso) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE estado=VALUES(estado),progreso=VALUES(progreso)');$s->execute([$u['id'],$id,$estado,$progreso]);}go('biblioteca.php');}top('Biblioteca');?><div class="layout"><?php sidebar();?><main><h1>Mi biblioteca</h1><div class="card"><h2>Añadir o actualizar lectura</h2><form method="post"><input type="hidden" name="csrf" value="<?=token()?>"><p><select name="libro_id" required><?php foreach(db()->query('SELECT id,titulo FROM libros ORDER BY titulo') as $b):?><option value="<?=$b['id']?>"><?=e($b['titulo'])?></option><?php endforeach;?></select></p><p><select name="estado"><option value="pendiente">Pendiente</option><option value="leyendo">Leyendo</option><option value="terminado">Terminado</option></select></p><p>Progreso (%) <input class="field" type="number" name="progreso" min="0" max="100" value="0"></p><button>Guardar lectura</button></form></div><?php $s=db()->prepare('SELECT b.*,l.titulo,a.nombre autor FROM bibliotecas b JOIN libros l ON l.id=b.libro_id LEFT JOIN autores a ON a.id=l.autor_id WHERE b.usuario_id=?');$s->execute([$u['id']]);foreach($s as $v):?><div class="card"><h3><?=e($v['titulo'])?></h3><p class="muted"><?=e($v['autor'])?> · <?=e($v['estado'])?></p><progress max="100" value="<?=$v['progreso']?>" style="width:100%"></progress> <?=$v['progreso']?>%</div><?php endforeach;?></main><?php rightbar();?></div><?php bottom();?>